package org.deposit.it;
import static org.junit.jupiter.api.Assertions.*;
import static org.deposit.it.AuthenticationNamespaceLifecycleIT.*;
import java.util.*;
import java.nio.file.*;
import org.junit.jupiter.api.*;

class HistoryRecoveryIT {
    @Test void persistentAndTransientRecoveryReceiptAndCursor()throws Exception {connect();try{var p=new Properties();try(var in=Files.newInputStream(ROOT.resolve("history-fixture.properties"))){p.load(in);}String token=BatchMutationIT.login();RevisionHistoryIT.token=token;BatchMutationIT.select(token,p.getProperty("persistent"));assertEquals(p.getProperty("head"),RevisionHistoryIT.head());assertEquals(Long.parseLong(p.getProperty("persistentSequence")),RevisionHistoryIT.seq());assertEquals(p.getProperty("geometry"),call("deposit.get.descriptor",m("objectId",p.getProperty("object"),"name","Geometry"),ctx(token)).get("data").get("geometryId").asString());assertEquals("YWJj",call("deposit.resource.downloadChunk",m("resourceId",p.getProperty("resource"),"offset",0L,"length",3L),ctx(token)).get("data").get("bytesBase64").asString());BatchMutationIT.select(token,p.getProperty("transient"));assertEquals(Long.parseLong(p.getProperty("transientSequence")),RevisionHistoryIT.seq());assertNotEquals(p.getProperty("transientHead"),RevisionHistoryIT.head());assertEquals(0,query("MATCH (r:Revision {id:$id}) RETURN count(r) AS n",m("id",p.getProperty("transientHead"))).getFirst().get("n").asInt());var retry=write(token,Long.parseLong(p.getProperty("expectedRevision")));retry.put("operationId",p.getProperty("operationId"));assertEquals(p.getProperty("transientHead"),call("deposit.utils.undo",m("revisionId",p.getProperty("target")),retry).get("data").get("revisionId").asString());assertEquals(Long.parseLong(p.getProperty("transientSequence")),RevisionHistoryIT.seq());error("REVISION_CONFLICT",()->call("deposit.get.historyPage",m("pageSize",1L,"cursor",p.getProperty("cursor")),ctx(token)));assertEquals(0,query("MATCH (e:DepositHistoryEpoch {namespaceId:$ns,mode:'transient',expired:true}) RETURN count(e) AS n",m("ns",p.getProperty("transient"))).getFirst().get("n").asInt());BatchMutationIT.select(token,p.getProperty("closedTransientNamespace"));assertNull(RevisionHistoryIT.head());assertEquals(Long.parseLong(p.getProperty("closedTransientSequence")),RevisionHistoryIT.seq());assertEquals(0,query("MATCH (r:Revision {id:$id}) RETURN count(r) AS n",m("id",p.getProperty("closedTransientHead"))).getFirst().get("n").asInt());BatchMutationIT.select(token,p.getProperty("promotedNamespace"));assertEquals(p.getProperty("promotedHead"),RevisionHistoryIT.head());assertTrue(call("deposit.utils.canUndo",m("revisionId",p.getProperty("promotedHead")),ctx(token)).get("value").asBoolean());}finally{close();}}
}
